import type { Lang } from "./types";

/* TETUN, PORTUGUESE, ENGLISH, INDONESIAN -- in that order, always.
 *
 * The order is positional and t() indexes into it, so a line with three
 * strings is a line that silently falls back to Tetun for a reader who
 * asked for Indonesian. The tuple type is what stops that: TypeScript
 * rejects the short line at the point it is written, and tests/i18n.test.ts
 * checks the built object as well, because a `as any` somewhere would slip
 * past the compiler and not past the test.
 *
 * INDONESIAN IS THE FOURTH and was added last, hence its position. It is
 * read by most Timorese schooled before 1999, by the shop's Indonesian
 * suppliers, and by visitors from West Timor -- see lib/locale.ts, which
 * gives it a URL prefix of its own rather than only a cookie. */
