export type StrKey = keyof typeof STR;

/** Where each language sits in the tuples above. One map, so adding a
 * fifth language is this line and the tuple type -- not a conditional
 * chain that compiles happily while pointing at the wrong column. */
const LANG_INDEX: Record<Lang, number> = { tet: 0, pt: 1, en: 2, id: 3 };

export function t(key: string, lang: Lang = "tet"): string {
  const e = STR[key];
  if (!e) return key;
  const idx = LANG_INDEX[lang] ?? 0;
  /* Falls back to Tetun rather than to the key. A string table that is a
     line short renders the shop's own language, which reads as an
     untranslated shop; rendering "announceNoRecipients" reads as a broken
     one. */
  return e[idx] ?? e[0];
}
